# max path/class case: 8192 paths
def layered(width, layers, offset=0):
    edges=[]
    def e(u,v): edges.append({"u":u,"v":v,"ping_us":1,"ack_us":2,"label":"%d%d"%(u%10,v%10)})
    src=offset; pre=offset+1
    e(src,pre)
    first=pre+1
    for k in range(width): e(pre, first+k)
    for L in range(layers-1):
